package ctf;

import java.util.*; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.jdbc.core.*; import org.springframework.web.bind.annotation.*; import org.springframework.context.annotation.*;
@SpringBootApplication @RestController public class ChallengeApplication { static JdbcTemplate db; public static void main(String[] a){SpringApplication.run(ChallengeApplication.class,a);} @Bean CommandLineRunner init(JdbcTemplate t){db=t; return x->{t.execute("CREATE TABLE IF NOT EXISTS users (id INT PRIMARY KEY, username VARCHAR, email VARCHAR, password VARCHAR)"); t.execute("CREATE TABLE IF NOT EXISTS secret_flag (flag VARCHAR)"); t.update("DELETE FROM secret_flag"); t.update("INSERT INTO secret_flag VALUES (?)",System.getenv().getOrDefault("FLAG","vladilk{local-sqli-update}")); t.update("MERGE INTO users KEY(id) VALUES (1,'alice','alice@example.test','password')");};}
@PostMapping("/") public String update(@RequestParam(defaultValue="1") String id,@RequestParam(defaultValue="") String email){String sql="UPDATE users SET email='"+email+"' WHERE id='"+id+"'"; try{db.execute(sql);return "<h1>Spring SQLi UPDATE</h1><pre>"+sql+"\nupdated</pre>"+profile(id);}catch(Exception e){return "<pre>H2 error: "+e.getMessage()+"</pre>";}}
@GetMapping("/") public String form(@RequestParam(defaultValue="1") String id){return "<h1>Spring SQLi UPDATE</h1><form method='post'><input name='id' value='1'><input name='email'><button>Update</button></form>"+profile(id);} String profile(String id){try{return "<pre>"+db.queryForList("SELECT * FROM users WHERE id='"+id+"'" )+"</pre>";}catch(Exception e){return "<pre>H2 error: "+e.getMessage()+"</pre>";}}
}
